#include "mods_service.h"
#include "frontend.h"
#include "mods_catalog_json.h"     // generated by CMakeLists.txt from the fetched tree's mods-catalog-2.json

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <mutex>
#include <thread>

namespace modinstall {
__attribute__((weak)) Fetcher* curl_fetcher();   // mi_fetch_curl.cpp, linked into the services program only
}

namespace fe {
modinstall::Manager& mod_manager() {
  // Never destroyed: a job still running when the app closes stops with the process (a partial download is continued
  // the next time; a partial disc is built again).
  static modinstall::Manager* manager = [] {
    modinstall::Config c;
    c.mods_dir = options.out_dir + "/mods";
    c.cache_dir = options.out_dir + "/mods-cache";
    c.disc_path = options.iso;
    c.catalog_json = kModsCatalogJson;
    c.fetcher = &modinstall::curl_fetcher ? modinstall::curl_fetcher() : nullptr;
    c.log = [](const std::string& line) { say("%s", line.c_str()); };
    auto* m = new modinstall::Manager(c);
    if (!m->catalog_ok()) say("mods: the built-in catalog was refused: %s", m->catalog_error().c_str());
    else say("mods: catalog of %zu mods; downloads %s; folder %s", m->catalog().size(), c.fetcher ? "available" : "not in this program (files go in mods/Downloads)", c.mods_dir.c_str());
    return m;
  }();
  return *manager;
}

// The catalog refreshed online (upstream launcher_mods.inl refresh_catalog): melee-unlocked's own raw catalog file, metadata
// only, fetched once per start by the services program; the copy is kept in mods-cache for the next start (a console offline).
// Applied by the screens' thread (mod_catalog_poll) when no job runs. Never in a session that cannot reach the network.
namespace {
constexpr const char* kCatalogUrl = "https://raw.githubusercontent.com/Hero88go/melee-unlocked/main/mods-catalog-2.json";
std::mutex g_refresh_mutex;
std::string g_refresh_json, g_refresh_from;
bool g_refresh_started = false;
std::string read_text(const std::string& path, size_t cap) {
  FILE* f = std::fopen(path.c_str(), "rb");
  if (!f) return {};
  std::string out; char buf[8192]; size_t n;
  while ((n = std::fread(buf, 1, sizeof buf, f)) > 0 && out.size() <= cap) out.append(buf, n);
  std::fclose(f);
  return out.size() > cap ? std::string() : out;
}
}  // namespace
void mod_catalog_poll() {
  auto& m = mod_manager();
  {
    std::lock_guard<std::mutex> lock(g_refresh_mutex);
    if (!g_refresh_started) {
      g_refresh_started = true;
      const std::string cache = options.out_dir + "/mods-cache/mods-catalog-2.json";
      g_refresh_json = read_text(cache, 1u << 20); g_refresh_from = "the copy kept from the last refresh";
      if (m.config().fetcher && !options.offline && std::getenv("MU_NO_CATALOG_REFRESH") == nullptr) {
        modinstall::Fetcher* fetcher = m.config().fetcher;
        std::thread([fetcher, cache] {
          const std::string part = cache + ".part";
          std::remove(part.c_str());
          const auto r = fetcher->fetch(kCatalogUrl, part, 0, [](uint64_t done, uint64_t) { return done < (1u << 20); });
          const std::string json = r.ok ? read_text(part, 1u << 20) : std::string();
          if (json.empty()) { say("mods: the catalog was not refreshed (%s); the built-in one stays", r.ok ? "empty or too large" : r.error.c_str()); std::remove(part.c_str()); return; }
          std::lock_guard<std::mutex> lock(g_refresh_mutex);
          g_refresh_json = json; g_refresh_from = "melee-unlocked's catalog online";
          std::remove(cache.c_str()); std::rename(part.c_str(), cache.c_str());
        }).detach();
      }
    }
  }
  std::string json, from;
  { std::lock_guard<std::mutex> lock(g_refresh_mutex); if (g_refresh_json.empty() || m.busy()) return; json.swap(g_refresh_json); from = g_refresh_from; }
  std::string error;
  if (m.replace_catalog(json, &error)) say("mods: catalog refreshed from %s: %zu mods", from.c_str(), m.catalog().size());
  else say("mods: the refreshed catalog (%s) was refused: %s; the built-in one stays", from.c_str(), error.c_str());
}

bool mod_downloads_available() { return &modinstall::curl_fetcher != nullptr; }
std::string mod_profile_next() { return settings_get("mod_profile"); }
bool mod_profile_set(const std::string& profile) { return settings_change("mod_profile", profile); }
std::vector<std::string> mod_profile_choices() {
  std::vector<std::string> out{""};
  for (const auto& p : mod_manager().profiles()) out.push_back(p);
  const std::string now = mod_profile_next();
  if (!now.empty() && std::find(out.begin(), out.end(), now) == out.end()) out.push_back(now);   // e.g. "hackpack,te" written by hand
  return out;
}
}  // namespace fe
